#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    string s;
    int n;
    cin >> s >> n;

    vector<int> freq(26, 0);
    for (char c : s) freq[c - 'a']++;

    // Find minimum number of sheets needed
    int sheets = 0;
    for (int i = 0; i < 26; i++) {
        if (freq[i] > 0) {
            int needed = (freq[i] + n - 1) / n; // ceil division
            sheets = max(sheets, needed);
        }
    }

    if (sheets == 0) {
        // s is empty, no sheets needed
        cout << 0 << "\n";
        cout << string(n, 'a') << "\n";
        return 0;
    }

    // Check if total stickers needed fit in sheets * n
    int total_needed = 0;
    for (int i = 0; i < 26; i++) {
        total_needed += freq[i];
    }
    if (sheets * n < total_needed) {
        cout << -1 << "\n";
        return 0;
    }

    // Construct the sheet string
    vector<int> sheet_freq(26, 0);
    for (int i = 0; i < 26; i++) {
        sheet_freq[i] = (freq[i] + sheets - 1) / sheets;
    }

    int sum_sheet = 0;
    for (int i = 0; i < 26; i++) sum_sheet += sheet_freq[i];

    if (sum_sheet > n) {
        cout << -1 << "\n";
        return 0;
    }

    // Fill remaining positions with 'a'
    string sheet;
    for (int i = 0; i < 26; i++) {
        sheet += string(sheet_freq[i], 'a' + i);
    }
    sheet += string(n - sum_sheet, 'a');

    cout << sheets << "\n" << sheet << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; cin >> n;
    string s; cin >> s;

    // If length is odd, no solution
    if (n % 2 == 1) {
        cout << ":(" << "\n";
        return 0;
    }

    int half = n / 2;
    int open = 0, close = 0;
    for (char c : s) {
        if (c == '(') open++;
        else if (c == ')') close++;
    }

    // If already too many '(' or ')', no solution
    if (open > half || close > half) {
        cout << ":(" << "\n";
        return 0;
    }

    // Replace '?' with '(' or ')' to balance counts
    int needOpen = half - open;
    int needClose = half - close;

    for (int i = 0; i < n; i++) {
        if (s[i] == '?') {
            if (needOpen > 0) {
                s[i] = '(';
                needOpen--;
            } else {
                s[i] = ')';
                needClose--;
            }
        }
    }

    // Check the sequence:
    // 1) The whole sequence must be correct parentheses
    // 2) All strict prefixes must NOT be correct parentheses

    // Check correctness of whole sequence
    int balance = 0;
    for (int i = 0; i < n; i++) {
        if (s[i] == '(') balance++;
        else balance--;
        if (balance < 0) {
            cout << ":(" << "\n";
            return 0;
        }
    }
    if (balance != 0) {
        cout << ":(" << "\n";
        return 0;
    }

    // Check all strict prefixes are NOT correct parentheses
    // A correct parentheses sequence must have balance never negative and end with balance 0.
    // So if any strict prefix has balance 0 at the end and never negative inside, it's correct.
    balance = 0;
    for (int i = 0; i < n - 1; i++) {
        if (s[i] == '(') balance++;
        else balance--;
        if (balance < 0) {
            // prefix invalid, continue
            continue;
        }
        if (balance == 0) {
            // prefix is correct parentheses sequence -> invalid
            cout << ":(" << "\n";
            return 0;
        }
    }

    cout << s << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    string s; cin >> s;

    // We want to count how many 4^k < s
    // 4^k = (2^2)^k = 2^(2k)
    // So we want max k such that 2^(2k) < s
    // => 2k < log2(s)
    // => k < log2(s)/2
    // The number of trains missed is floor((log2(s)-1)/2) + 1 if s > 1, else 0

    // Since s is binary string, log2(s) = length(s)-1 (index of highest set bit)
    // We want to find max k with 2^(2k) < s
    // 2^(2k) < s
    // 2k < log2(s)
    // k < (log2(s))/2

    // So number of trains missed = number of k >= 0 with 2k < log2(s)
    // = floor((log2(s)-1)/2) + 1 if s > 1 else 0

    // But we must be careful with exact comparison because s can be any number.

    // Let's implement a binary search on k:
    // For k in [0..50] (since 2^(2*50)=2^100, max time)
    // check if 4^k < s

    // We'll implement comparison of 4^k and s as strings.

    // Function to compute 4^k as binary string
    // 4^k = 2^(2k), so binary string is '1' followed by 2k zeros

    auto less_than = [&](int k) {
        // 4^k in binary: '1' + 2k zeros
        int len_4k = 1 + 2*k;
        if ((int)s.size() > len_4k) return true;
        if ((int)s.size() < len_4k) return false;
        // same length, compare lex
        // 4^k = '1' + 2k zeros
        // s is length len_4k
        // s[0] must be '1' to be equal or greater
        if (s[0] < '1') return true;
        if (s[0] > '1') return false;
        // compare rest zeros with s[1..]
        for (int i = 1; i < len_4k; i++) {
            if (s[i] < '0') return true;
            if (s[i] > '0') return false;
        }
        // equal
        return false; // 4^k == s means not less than s
    };

    int left = 0, right = 50;
    int ans = -1;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (less_than(mid)) {
            ans = mid;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    cout << (ans + 1) << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int k; cin >> k;
    while (k--) {
        int n; cin >> n;
        string s, t;
        cin >> s >> t;

        // Find positions where s and t differ
        vector<int> diff;
        for (int i = 0; i < n; i++) {
            if (s[i] != t[i]) diff.push_back(i);
        }

        // If more than 2 differences, impossible with one swap
        if (diff.size() > 2) {
            cout << "No\n";
            continue;
        }

        // If exactly 2 differences, try swapping s[diff[0]] with t[diff[1]] or s[diff[1]] with t[diff[0]]
        if (diff.size() == 2) {
            int i = diff[0], j = diff[1];
            // Try swap s[i] and t[j]
            swap(s[i], t[j]);
            if (s == t) {
                cout << "Yes\n";
                continue;
            }
            // revert and try swap s[j] and t[i]
            swap(s[i], t[j]);
            swap(s[j], t[i]);
            if (s == t) {
                cout << "Yes\n";
                continue;
            }
            cout << "No\n";
            continue;
        }

        // If exactly 1 difference, try all possible swaps s[i] and t[j]
        if (diff.size() == 1) {
            int pos = diff[0];
            bool can = false;
            for (int j = 0; j < n; j++) {
                swap(s[pos], t[j]);
                if (s == t) {
                    can = true;
                    swap(s[pos], t[j]);
                    break;
                }
                swap(s[pos], t[j]);
            }
            cout << (can ? "Yes\n" : "No\n");
            continue;
        }

        // If no differences, strings are equal but must do exactly one swap
        // Swapping s[i] and t[j] where s[i] != t[j] is impossible since strings are equal
        // But strings are distinct per problem statement, so this case won't occur
        cout << "No\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; cin >> n;
    vector<long long> A(n);
    for (int i = 0; i < n; i++) cin >> A[i];

    int m; cin >> m;
    vector<long long> B(m);
    for (int i = 0; i < m; i++) cin >> B[i];

    int i = 0, j = 0;
    long long sumA = 0, sumB = 0;
    int count = 0;

    while (i < n && j < m) {
        if (sumA == sumB) {
            sumA = A[i++];
            sumB = B[j++];
            count++;
        } else if (sumA < sumB) {
            if (i == n) break;
            sumA += A[i++];
        } else {
            if (j == m) break;
            sumB += B[j++];
        }
    }

    // After the loop, if sums are equal and all elements processed, print count
    if (sumA == sumB && i == n && j == m) {
        cout << count << "\n";
    } else {
        cout << -1 << "\n";
    }

    return 0;
}
